-- 0010 · DLP de convivencia: variantes y huecos de las reglas de lenguaje de 0008.
-- La auditoría de foros, hilos y salas encontró groserías, insultos dirigidos, amenazas,
-- lenguaje sexual y doble sentido que pasaban (en inglés, abreviados, con «ñ», como mensaje
-- completo o con una palabra de «contexto» agregada para esquivar las excepciones). Agrega
-- reglas nuevas sin reactivar las que la administración haya desactivado, y corrige un falso
-- positivo de 0008 solo si su patrón no se ha cambiado desde entonces.
-- Las mismas reglas están en db/seed/reglas_dlp.json; test/dlp-lenguaje.test.ts comprueba que
-- los patrones de los dos archivos sean idénticos. Mientras esta migración no se aplique, el
-- DLP usa igual las reglas nuevas del seed (dlp.repository.ts → reglasActivas).

insert into app.regla_dlp (codigo, categoria, descripcion, patron) values
  ('ofensivo-groserias-variantes', 'lenguaje_ofensivo',
   'Variantes y derivados de groserías que las reglas de 0008 no cubrían: putica, putón, mrd, pndj, alv, coño, cagada, jodido, güevada, comemierda, gonorreíta, hijueputica, jeputa, marikón, chupapija, pajero, «que te jodan».',
   '\bput(?:ic[oa]s?|it[oa]s?|on(?:a|es|as)?|ota|otas|azo|azos)\b|\bmrd[ao]?s?\b|\bpndj[oa]?s?\b|\balv\b|\b[ck]ony(?:o|a|os|as|azo|azos)\b|\bmierd(?:ero|era|eros|eras|ecita|ecitas)\b|\bcag(?:ada|adas|ar|aste|aron|ando|ado|ados|ao|ue|uen|uemos|alera)\b|\bme\s+cago\b|\bjodid[oa]s?\b|\bjodienda\b|\bg[uw]e[bv]as?\b|\bque\s+hue[bv]a\b|\bh?[gw]?ue[bv]ad(?:a|as|ita|itas)\b|\b[bv]err?gaci(?:on|ones)\b|\bql[oa]s?\b|\bqliao\b|\b(?:come|lame|chupa|traga|cara\s+de|saco\s+de)\s?mierdas?\b|\bgonorr?e(?:ita|itas|ota|otas|on|ona)\b|\bgnrr?\b|\bmlprd[oa]?s?\b|\bmalparid(?:ez|eces|ito|ita|itos|itas)\b|\b(?:h?ij?|j)[uv]e\s?p[uv]t(?:ez|ic[oa]s?|it[oa]s?|azo|ota)?\b|\bh?iju?ep\b|\bje\s?p[uv]t[ao]s?\b|\bmarik(?:a|as|o|os|on|ona|ones|onas)?\b|\bchupa\s?(?:pijas?|pingas?|[bv]err?gas?|pollas?|pichas?|picos?|mondas?|h?[gw]?ue[bv]os)\b|\bchucha\s+(?:de\s+)?(?:tu|su)\s+madre\b|(?<!\b(?:una|la|mitsubishi|camioneta|carro)\s)\bpajer[oa]s?\b|\bque\s+te\s+jodan\b|^\W*que\s+te\s+den\W*$'),
  ('ofensivo-dirigido-variantes', 'lenguaje_ofensivo',
   'Insultos dirigidos que se escapaban: «gonorrea» y «hp» dirigidos aunque el mensaje mencione salud o juegos, el insulto como mensaje completo («idiota», «zorra»), «eres demasiado idiota», «gorda asquerosa», «sapa perra», «das asco», «nadie te quiere». La palabra suelta dentro de una frase sigue permitida.',
   '\b(?:eres|sos|usted\s+es|ustedes\s+son|ese|esa|esos|esas|man|vieja|viejo|parce|so|pedazo\s+de|que|tan)\s+(?:(?:un|una|re|tan|muy|tremend[oa]|la\s+mas|el\s+mas)\s+)?gonorr?e(?:a|ita|ota)s?\b|\b(?:es|son)\s+(?:un|una)\s+(?:(?:re|tremend[oa])\s+)?gonorr?eas?\b|^gonorr?eas?\s*[,!¡]|\b(?:eres|sos|usted\s+es|ustedes\s+son)\s+(?:(?:un|una|unos|unas|re|tremend[oa]|gran)\s+)?hps?\b(?!\s*(?:\d|de\b|en\b))|\b(?:sap[oa]|malparid[oa]|gonorrea|marica|perr[oa]|negr[oa]|indi[oa]|maldit[oa]|bob[oa]|ladron|ladrona|gamin|pirob[oa]|rata|gord[oa]|cerd[oa]|zorr[oa]|vieja|viejo|man|parce)\s+hps?\b(?!\s*\d)|^[^a-z0-9]*(?:idiotas?|estupid[oa]s?|imbecil(?:es)?|tarad[oa]s?|retrasad[oa]s?|subnormal(?:es)?|mongolic[oa]s?|mogolic[oa]s?|malnacid[oa]s?|desgraciad[oa]s?|cretin[oa]s?|anormal(?:es)?|pelotud[oa]s?|cojud[oa]s?|zorr+as?|perr+as?|escorias?|lacras?|bastard[oa]s?)[^a-z0-9]*$|\b(?:eres|sos|ere|eri|es\s+usted)\s+(?:(?:un|una|demasiado|bastante|super|requete|re|muy|tan|mas|bien)\s+){0,2}(?:idiotas?|estupid[oa]s?|imbecil(?:es)?|tarad[oa]s?|retrasad[oa]s?|subnormal(?:es)?|mongolic[oa]s?|mogolic[oa]s?|malnacid[oa]s?|desgraciad[oa]s?|cretin[oa]s?|anormal(?:es)?|pelotud[oa]s?|cojud[oa]s?)\b|\bque\s+(?:tan|re|muy|mas)\s+(?:idiotas?|estupid[oa]s?|imbecil(?:es)?|tarad[oa]s?|retrasad[oa]s?|subnormal(?:es)?|mongolic[oa]s?|mogolic[oa]s?|malnacid[oa]s?|desgraciad[oa]s?|cretin[oa]s?|anormal(?:es)?|pelotud[oa]s?|cojud[oa]s?)\s+(?:eres|sos|es|son)\b|\bretrasad[oa]s?\s+mental(?:es)?\b|\b(?:sap[oa]|maldit[oa]|pinche|asqueros[oa]|hijueput[oa]|malparid[oa]|gonorrea|zorr?a|gord[oa]|fe[oa]|negr[oa]|indi[oa]|cerd[oa]|enan[oa]|venec[oa]|marica|maricon|bob[oa]|tont[oa]|vieja|viejo)\s+(?:perr?[oa]s?|zorr?[oa]s?|ratas?|cerd[oa]s?|asqueros[oa]s?|inmund[oa]s?|repugnantes?|hijueput[oa]s?|malparid[oa]s?)\b|\b(?:me\s+)?das\s+asco\b|\bnadie\s+te\s+(?:quiere|soporta|aguanta)(?:\s+(?:aqui|aca|en\s+(?:este|el|la|esta)\s+(?:grupo|sala|foro|colegio)))?\s*(?:[.,!?]|$)'),
  ('ofensivo-amenazas', 'lenguaje_ofensivo',
   'Amenazas de violencia física o sexual dirigidas a otra persona («te voy a violar», «te voy a matar», «te parto la cara»). «Te mato a besos» o «me muero de la risa» no se bloquean.',
   '\bte\s+(?:(?:voy|vamos|van)\s+a\s+|quiero\s+|puedo\s+)?(?:violar|viol(?:o|are|aria))\b|\b(?:violarte|violarla|violarlo|violarlos|violarlas)\b|\bte\s+(?:(?:voy|vamos|van)\s+a\s+)?(?:matar|mato|matare|mataria|apunalar|apunalo|acuchillar|acuchillo|chuzar|chuzo|balear|baleo)\b(?!\s+(?:a\s+besos|de\s+(?:la\s+)?risa|a\s+cosquillas))|\b(?:voy|vamos)\s+a\s+(?:matarte|apunalarte|acuchillarte|chuzarte|balearte|matarlos|matarlas)\b|\bte\s+(?:(?:voy|vamos)\s+a\s+)?(?:parto|partir|rompo|romper|reviento|reventar|quiebro|quebrar|vuelo|volar|tumbo|tumbar)\s+(?:la\s+(?:cara|jeta|boca|madre|nariz|cabeza)|el\s+(?:hocico|craneo)|los\s+dientes)\b'),
  ('ofensivo-ingles', 'lenguaje_ofensivo',
   'Groserías e insultos en inglés (fuck y variantes, wtf, stfu, shit, bitch, asshole, whore, slut e insultos racistas u homófobos). «Shiitake» o «Dick Tracy» no se bloquean.',
   '\b(?:f[uv]+c*k+|fc+k+|fuk+)(?:s|ing|in|ed|er|ers|off|face|head|boy|tard)?\b|\bmother\s?f[uv]*c*k+\w*|\b(?:wtf|stfu|gtfo)\b|\b(?:bull|horse|dip)?shit(?:s|ty|head|post\w*|ass)?\b|\bbitch(?:es|y|in|ing)?\b|\bson\s+of\s+a\s+bitch\b|\bass\s?holes?\b|\bdumb\s?ass(?:es)?\b|\bdick\s?heads?\b|\b(?:cunts?|whores?|sluts?|niggas?|niggers?|faggots?|retards?|bastards?)\b'),
  ('sexual-ingles', 'contenido_sexual',
   'Lenguaje sexual en inglés y sitios pornográficos (porn, pornhub, xvideos, hentai, horny, boobs, pussy, send nudes…). «Cum laude» no se bloquea.',
   '\b(?:porn|porns|pornhub|xvideos|xnxx|xhamster|redtube|youporn|brazzers|chaturbate|hentai|nsfw|milfs?|dildos?)\b|\brule\s?34\b|\b(?:blow|hand)\s?jobs?\b|\bjerk(?:ing)?\s+off\b|\bsex\s?(?:tape|cam)\b|\bcamgirls?\b|\bcum(?:shot|ming)\b|\bcum\b(?!\s+laude)|\b(?:horny|boobs|boobies|tits|titties|pussy|pussies|cocks?)\b|\b(?:my|your|his|suck\s+(?:my|a|your))\s+dicks?\b|\bdick\s?pics?\b|\bsend\s+(?:me\s+)?(?:nudes?|pics)\b'),
  ('sexual-dirigido-variantes', 'contenido_sexual',
   'Comentarios, propuestas y doble sentido sexual dirigidos que se escapaban: «estás sexy», «qué rica estás», «me pones caliente», «hagamos el delicioso», «quiero tocarte», «te quiero comer», «la tienes grande», «siéntate en mi cara», «muéstrame tu pene» (aunque el mensaje mencione al médico). Las palabras sueltas (caliente, comer, tocar, duro) no se bloquean.',
   '\b(?:estas|te\s+ves|andas)\s+(?:muy\s+|bien\s+|re\s+|tan\s+|super\s+|bastante\s+)?(?:sexy|sexi|deliciosa|delicioso|hot|buenota|buenote|cachond[oa]|mamacita|mamasita|rica|rico)\b|\bque\s+(?:rica|rico|buenota|buenote|sabrosa|sabroso|deliciosa|delicioso|sexy|hot)\s+(?:estas|te\s+ves|andas)\b|\bque\s+buen[oa]\s+(?:estas|te\s+ves)\s*[.!?]*$|\bme\s+(?:pones|tienes|dejas)\s+(?:muy\s+|bien\s+|re\s+|tan\s+|todo\s+|toda\s+)?(?:caliente|calientes|arrech[oa]|cachond[oa]|hot|horny|exitad[oa]|excitad[oa]|mojad[oa])\b|\bme\s+(?:excitas|exitas|calientas)\b|\bme\s+(?:prendes|mojas)\b(?!\s+(?:el|la|los|las|un|una|con|fuego)\b)|\b(?:estoy|ando|quede)\s+(?:muy\s+|bien\s+|re\s+|todo\s+|toda\s+)?(?:caliente|arrech[oa]|cachond[oa]|horny|excitad[oa]|exitad[oa]|mojad[oa]|dur[oa])\s+(?:pensando\s+en\s+ti|por\s+ti|contigo|viendote|de\s+verte|al\s+verte)\b|\bquiero\s+sexo\b|\b(?:tengamos|hagamos)\s+relaciones(?:\s+sexuales)?\s*(?:[.!?]|$|tu\s+y\s+yo|juntos|contigo|conmigo)|\btener\s+relaciones(?:\s+sexuales)?\s+(?:contigo|conmigo)\b|\b(?:hagamos|hacer|hacemos|hacerlo|hicimos|haciendo)\s+(?:lo|el)\s+delicioso\b|\b(?:hagamos|hacerte|hacerme|hacernos|te\s+hago|te\s+haria|te\s+hare)\s+cositas\b|\bhacerte\s+el\s+amor\b|\bte\s+(?:hago|hare|haria)\s+el\s+amor\b|\bte\s+(?:(?:voy|vamos)\s+a\s+|quiero\s+|puedo\s+)hacer\s+el\s+amor\b|\bhacer\s+el\s+amor\s+(?:contigo|conmigo)\b|\bbesarte\s+(?:todo\s+el\s+cuerpo|toda|todito|todita|ahi\s+abajo|alla\s+abajo)\b|\b(?:dejame|quiero|puedo|voy\s+a|me\s+dejas|quisiera|me\s+gustaria)\s+tocarte\b(?!\s+(?:una|un|la|el|esta|este|mi|algo)\b)|\bte\s+(?:quiero|voy\s+a|puedo|quisiera)\s+tocar\b(?!\s+(?:una|un|la|el|esta|este|mi|algo|en|con)\b)|\btocar(?:te)?\s+(?:tus|sus)\s+(?:partes\s+intimas|nalgas|tetas|senos|pechos|piernas|cosita)\b|\b(?:quiero|voy\s+a|dejame|me\s+dejas|quisiera)\s+(?:chuparte|mamarte|lamerte)\b(?!\s+(?:la\s+(?:sangre|cara|mano)|el\s+helado))|\bme\s+la\s+(?:chupes|mames|chupen|mamen|lamas)\b|(?:^|[¿?!,.]\s*|\bque\s+|\bsi\s+)(?:la|lo)\s+(?:tienes|tengo|tiene|tenes)\s+(?:muy\s+|bien\s+|re\s+|tan\s+)?(?:grande|grandota|gorda|gordo|larga|largo|dura|duro|parada|parado)\b(?!\s+(?:la|el|mi|tu)\b)|\bque\s+(?:grande|gorda|larga|dura|rica)\s+la\s+(?:tienes|tenes|tiene)\b|\b(?:mi|tu|su)\s+(?:[bv]err?ga|pinga|monda|picha|pito|polla|chimba|chocha|panocha)\s+(?:es\s+|esta\s+)?(?:(?:muy|bien|tan|re)\s+)?(?:grande|gorda|enorme|larga|rica|parada|dura|mojada|apretada)\b|\b(?:mete|clava|ensarta|hunde)mela\b|\bsientate\s+(?:en|sobre)\s+(?:mi|mis)\s+(?:cara|piernas|regazo|pene|[bv]err?ga|pinga|pito|boca|paquete)\b|\bsientate\s+encima\s+(?:de\s+)?mi\b|\bsentadit[oa]\s+(?:en|sobre)\s+(?:mi|mis)\b(?!\s+(?:casa|silla|puesto|cuarto|pupitre))|\bcabalg(?:ame|arte)\b|\bmontate\s+(?:encima|sobre\s+mi)\b|\bte\s+(?:monto|montaria|quiero\s+montar|voy\s+a\s+montar)\b(?!\s+(?:en|una|un|la|el|a|al)\b)|\bme\s+(?:vine|vengo|corro|corri)\s+(?:en\s+(?:ti|tu\s+(?:boca|cara|culo|cuca))|dentro\s+de\s+ti|adentro\s+de\s+ti|encima\s+de\s+ti)\b|\bcomete\s+(?:este|esta|mi)\s+(?:pico|pito|pene|[bv]err?ga|pinga|chimba|polla|monda|picha|cuca)\b|\bcomeme\b(?!\s+(?:la|el|las|los)\b)|\b(?:quiero|me\s+gustaria|voy\s+a|vamos\s+a|dejame|quisiera)\s+comerte\b(?!\s+a\s+besos)|\bte\s+(?:quiero|voy\s+a|gustaria|quisiera)\s+comer\b(?!\s+(?:a\s+besos|el|la|los|las|tu|tus|mi|un|una|algo|con|en|de)\b)|\bte\s+comeri?a\b(?!\s+(?:a\s+besos|el|la|los|las|tu|tus|mi|un|una|algo|con|en|de)\b)|\bdamelo\s+(?:bien\s+|mas\s+|re\s+)?duro\b|\bdame\s+(?:bien\s+|mas\s+)?duro\b(?!\s+(?:en|con|al|a)\b)|\bte\s+(?:voy\s+a\s+dar|doy|dare|daria)\s+(?:bien\s+|mas\s+)?duro\s*[.!?]*$|\bque\s+(?:buenas|ricas|lindas|grandes|tremendas|hermosas|sabrosas)\s+(?:nalgas|tetas|teticas|senos|pechos|chichis|bubis|piernotas)\b|\bque\s+(?:nalgas|nalgotas|nalgona|tetotas|culazo|culote|culito)\b|\b(?:buen[oa]s|ric[oa]s|tremend[oa]s|sabros[oa]s)\s+(?:nalgas|tetas|teticas|senos|culo|culito)\b|\bnalgon[ao]s?\b|\btienes\s+(?:buenas|ricas|grandes)\s+(?:nalgas|tetas|senos|pechos|curvas)\b|\bmama\s?(?:hu?|u)e[bv]os?\b|\bmama\s?bichos?\b|\b(?:muestrame|ensename|mandame|pasame|enviame|dejame\s+ver|quiero\s+ver)\s+(?:tu|tus)\s+(?:pito|pene|[bv]err?ga|pinga|cuca|vagina|chocho|culo|nalgas|tetas|senos|pechos|partes\s+intimas|cosita|chimba|panocha|polla)\b|\b(?:tocame|chupame|mamame|lameme|agarrame|sobame)\s+(?:(?:el|la|los|las|mi|mis)\s+)?(?:pito|pene|[bv]err?ga|pinga|cuca|vagina|chocho|culo|nalgas|tetas|senos|pechos|partes\s+intimas|cosita|chimba|panocha|polla|huevos|bolas)\b|\b(?:abre|abrete|abreme)\s+(?:las|tus)\s+(?:piernas|nalgas)\s+(?:para\s+mi|pa\s+mi|por\s+mi|mami|mamita|bebe|nena|amor)\b')
on conflict (codigo) do nothing;

-- sexual-explicito: «hagámoslo» solo se bloquea con contexto sexual («hagámoslo rico», «hagámoslo en la cama»): «hagámoslo juntos» o «hagámoslo bien esta vez» son frases de trabajo en grupo.
update app.regla_dlp
set patron = '\b[ck][uv]l(?:i|e)(?:ar|arte|arla|arlo|arme|arnos|ando|ado|ada|ados|adas|ao|amos|emos|en|o|a)\b|\bfoll?(?:ar|arte|arla|arlo|ame|amos|ando|o|e|en|aria)\b|\bpajea(?:r|rse|rte|rme|ndo|ndome|ndose)\b|\bpajeo\b|\bhacer(?:se|te|me|nos)\s+(?:una\s+|la\s+)?paja\b|\bme\s+hago\s+(?:una\s+|la\s+)?paja\b|\b(?:me|te|se)\s+la\s+(?:jalo|jalas|jala|jale|halo|halas|sacudo)\b|\bjalar(?:se|te|me)la\b|\b(?:masturb\w+|me\s+toco|me\s+vengo|me\s+mojo)\s+(?:pensando\s+en\s+ti|viendote|contigo|con\s+tus?\s+fotos?)\b|\bpingas?\b|\bpichas?\b|\btet(?:as|otas|ona|onas|ota)\b|\bcachond[oa]s?\b|\bporno(?:s)?\b|\bxxx\b|\bnudes\b|\b(?:un|una|tus|tu|el|tienes)\s+nude\b|\bsexting\b|\b(?:pasa|pasame|manda|mandame|envia|enviame|vende|vendo|tienes|tenes|quiero|regalame|muestrame|comparte|compartime)\s+(?:(?:el|tu|un|ese|algun|su|tus)\s+)?packs?\b(?!\s+de\b)|\bsexo\s+(?:oral|anal|por\s+(?:camara|video|videollamada|chat)|virtual\s+conmigo|virtual\s+contigo)\b|\b(?:hagamos|tengamos|hacemos|tenemos)\s+(?:el\s+)?sexo\b|\bhagamoslo\s+(?:rico|riquito|contigo|mami|mamita|papi|papito|bebe|nena|sin\s+condon|duro|en\s+(?:la\s+cama|mi\s+cuarto|tu\s+cuarto|el\s+bano))\b|\bsexo\s+(?:\w+\s+)?(?:contigo|conmigo)\b|\b(?:hacerlo|acostarme|acostarnos|culiar|tirar)\s+contigo\b|\bhagamos\s+el\s+amor\b',
    fecha_actualizacion = now()
where codigo = 'sexual-explicito'
  and patron = '\b[ck][uv]l(?:i|e)(?:ar|arte|arla|arlo|arme|arnos|ando|ado|ada|ados|adas|ao|amos|emos|en|o|a)\b|\bfoll?(?:ar|arte|arla|arlo|ame|amos|ando|o|e|en|aria)\b|\bpajea(?:r|rse|rte|rme|ndo|ndome|ndose)\b|\bpajeo\b|\bhacer(?:se|te|me|nos)\s+(?:una\s+|la\s+)?paja\b|\bme\s+hago\s+(?:una\s+|la\s+)?paja\b|\b(?:me|te|se)\s+la\s+(?:jalo|jalas|jala|jale|halo|halas|sacudo)\b|\bjalar(?:se|te|me)la\b|\b(?:masturb\w+|me\s+toco|me\s+vengo|me\s+mojo)\s+(?:pensando\s+en\s+ti|viendote|contigo|con\s+tus?\s+fotos?)\b|\bpingas?\b|\bpichas?\b|\btet(?:as|otas|ona|onas|ota)\b|\bcachond[oa]s?\b|\bporno(?:s)?\b|\bxxx\b|\bnudes\b|\b(?:un|una|tus|tu|el|tienes)\s+nude\b|\bsexting\b|\b(?:pasa|pasame|manda|mandame|envia|enviame|vende|vendo|tienes|tenes|quiero|regalame|muestrame|comparte|compartime)\s+(?:(?:el|tu|un|ese|algun|su|tus)\s+)?packs?\b(?!\s+de\b)|\bsexo\s+(?:oral|anal|por\s+(?:camara|video|videollamada|chat)|virtual\s+conmigo|virtual\s+contigo)\b|\b(?:hagamos|tengamos|hacemos|tenemos)\s+(?:el\s+)?sexo\b|\bhagamoslo\b|\bsexo\s+(?:\w+\s+)?(?:contigo|conmigo)\b|\b(?:hacerlo|acostarme|acostarnos|culiar|tirar)\s+contigo\b|\bhagamos\s+el\s+amor\b';
